style.css:
/* Sakura Pink */
body { background: #FFF8FA !important; color: #644D63 !important; }
h1, h2, h3 { color: #D58DAF !important; }
p { color: #8C7188 !important; }
a { color: #CF83A8 !important; }
button {
  background: #F8BBD0 !important;
  color: #634357 !important;
  border: 1px solid #E6A4C0 !important;
  border-radius: 15px !important;
}
input, textarea {
  background: #FADADD !important;
  color: #644D63 !important;
  border: 1px solid #E6C9E8 !important;
}
::selection { background: #E6A4C0; color: white; }
